const test = require('node:test');
const assert = require('node:assert/strict');
const { loadPreference } = require('../preferences.cjs');
test('both synchronous and asynchronous ENOENT use the fallback', async () => {
  const defaults = Object.freeze({theme:'light',font:16});
  const missing = Object.assign(new Error('missing preferences'),{code:'ENOENT'});
  let calls = 0;
  let actual;
  await assert.doesNotReject(async () => {
    actual = await loadPreference(() => { calls++; return Promise.reject(missing); },defaults);
  });
  assert.strictEqual(actual,defaults); assert.equal(calls,1);
  assert.strictEqual(await loadPreference(() => { throw missing; },defaults),defaults);
  const saved = Object.freeze({theme:'dark',font:18});
  assert.strictEqual(await loadPreference(() => Promise.resolve(saved),defaults),saved);
  assert.strictEqual(await loadPreference(() => saved,defaults),saved);
  for (const code of ['EACCES','EINVAL']) {
    const error = Object.assign(new Error('unreadable'),{code});
    await assert.rejects(loadPreference(() => Promise.reject(error),defaults),caught => caught === error);
    await assert.rejects(loadPreference(() => { throw error; },defaults),caught => caught === error);
  }
});

test('every path calls reader once with no arguments', async () => {
  const defaults = Object.freeze({theme:'light'});
  const saved = Object.freeze({theme:'dark'});
  const missing = Object.assign(new Error('missing'),{code:'ENOENT'});
  const denied = Object.assign(new Error('denied'),{code:'EACCES'});
  const uncoded = new Error('unknown failure');
  for (const asynchronous of [false,true]) {
    for (const error of [null,missing,denied,uncoded]) {
      let calls = 0;
      const reader = (...args) => {
        calls++;
        assert.deepEqual(args,[]);
        if (asynchronous) return error ? Promise.reject(error) : Promise.resolve(saved);
        if (error) throw error;
        return saved;
      };
      if (error && error !== missing) {
        await assert.rejects(loadPreference(reader,defaults),caught => caught === error);
      } else {
        assert.strictEqual(await loadPreference(reader,defaults),error ? defaults : saved);
      }
      assert.equal(calls,1);
    }
  }
});

